import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv2d_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16
#define BLOCK_SIZE 256

__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int in_channels, int out_channels,
    int input_height, int input_width,
    int output_height, int output_width,
    int kernel_size,
    int stride,
    int padding,
    int groups,
    bool use_bias)
{
    const int batch = blockIdx.z;
    const int oc = blockIdx.x * blockDim.x + threadIdx.x;
    const int oh = blockIdx.y / output_width;
    const int ow = blockIdx.y % output_width;

    if (oc >= out_channels || oh >= output_height || ow >= output_width || batch >= gridDim.z)
        return;

    const int in_channels_per_group = in_channels / groups;
    const int out_channels_per_group = out_channels / groups;
    const int group = oc / out_channels_per_group;

    float sum = 0.0f;

    for (int ic = 0; ic < in_channels_per_group; ++ic) {
        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                const int ih = oh * stride - padding + kh;
                const int iw = ow * stride - padding + kw;

                if (ih >= 0 && ih < input_height && iw >= 0 && iw < input_width) {
                    const int input_idx = batch * in_channels * input_height * input_width +
                                        (group * in_channels_per_group + ic) * input_height * input_width +
                                        ih * input_width +
                                        iw;

                    const int weight_idx = oc * (in_channels / groups) * kernel_size * kernel_size +
                                         ic * kernel_size * kernel_size +
                                         kh * kernel_size +
                                         kw;

                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    if (use_bias)
        sum += bias[oc];

    const int output_idx = batch * out_channels * output_height * output_width +
                          oc * output_height * output_width +
                          oh * output_width +
                          ow;

    output[output_idx] = sum;
}

torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool use_bias)
{
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto input_height = input.size(2);
    auto input_width = input.size(3);
    auto out_channels = weight.size(0);

    int output_height = (input_height + 2 * padding - kernel_size) / stride + 1;
    int output_width = (input_width + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::zeros({batch_size, out_channels, output_height, output_width}, input.options());

    dim3 grid_dim(
        (out_channels + BLOCK_SIZE - 1) / BLOCK_SIZE,
        output_height * output_width,
        batch_size
    );

    conv2d_forward_kernel<<<grid_dim, BLOCK_SIZE>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        use_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        in_channels, out_channels,
        input_height, input_width,
        output_height, output_width,
        kernel_size,
        stride,
        padding,
        groups,
        use_bias
    );

    return output;
}
"""

conv2d_cpp = "torch::Tensor conv2d_forward_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int kernel_size, int stride, int padding, int dilation, int groups, bool use_bias);"

conv2d_ext = load_inline(
    name="conv2d_ext",
    cpp_sources=conv2d_cpp,
    cuda_sources=conv2d_kernel_source,
    functions=["conv2d_forward_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.use_bias = bias

        self.weight = nn.Parameter(torch.empty(
            out_channels, in_channels // groups, kernel_size, kernel_size
        ))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv2d_ext.conv2d_forward_cuda(
            x, self.weight, 
            self.bias if self.use_bias else torch.zeros_like(self.bias),
            self.kernel_size, self.stride, self.padding,
            self.dilation, self.groups, self.use_bias
        )
